import React, { useEffect, useState } from 'react';
import { Loader2, ChevronDown, PlayCircle, Star } from 'lucide-react';

function App() {
  const [course, setCourse] = useState(null);
  const [loading, setLoading] = useState(false);
  const [avgReviewCount, setAvgReviewCount] = useState(0);
  const [confirmationModal, setConfirmationModal] = useState(false);
  const [openSectionsArray, setOpenSectionsArray] = useState([]);

  const loadCourseDetails = async () => {
    setLoading(true);
    try {
      // Simulated API call
      const result = await new Promise((resolve) => {
        setTimeout(() => {
          resolve({
            data: {
              id: '1',
              courseName: 'Advanced Web Development',
              courseDescription: 'Master modern web development with this comprehensive course',
              price: 99.99,
              instructor: {
                firstName: 'John',
                lastName: 'Doe',
                image: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=400&h=400&fit=crop'
              },
              whatYouWillLearn: 'Build professional web applications with React, Node.js, and modern tools',
              courseContent: [
                {
                  sectionName: 'Getting Started',
                  subSection: [
                    {
                      title: 'Course Introduction',
                      description: 'Overview of what you will learn'
                    },
                    {
                      title: 'Setting Up Your Development Environment',
                      description: 'Install and configure necessary tools'
                    }
                  ]
                },
                {
                  sectionName: 'Advanced Concepts',
                  subSection: [
                    {
                      title: 'State Management',
                      description: 'Learn about state management patterns'
                    },
                    {
                      title: 'Performance Optimization',
                      description: 'Techniques for optimizing your applications'
                    }
                  ]
                }
              ],
              ratingAndReview: [{ rating: 5 }, { rating: 4 }, { rating: 5 }],
              studentsEnrolled: ['1', '2', '3', '4', '5']
            }
          });
        }, 1000);
      });

      if (!result) {
        console.log('No course found');
        return;
      }
      setCourse(result.data);
    } catch (err) {
      console.log('Error occurred while fetching course details:', err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadCourseDetails();
  }, []);

  useEffect(() => {
    if (course) {
      const avgRating = course.ratingAndReview.reduce((acc, curr) => acc + curr.rating, 0) / course.ratingAndReview.length;
      setAvgReviewCount(avgRating);
    }
  }, [course]);

  if (loading) {
    return (
      <div className="h-full w-full flex justify-center items-center min-h-screen">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  const isOpen = (index) => openSectionsArray.includes(index);

  return (
    <>
      <div className="bg-gray-900 flex flex-col items-start">
        {/* Section 1 */}
        <div className="w-11/12 max-w-7xl mx-auto relative text-white flex justify-between items-start py-24">
          <div className="flex flex-col gap-4">
            <h1 className="text-4xl font-bold">{course?.courseName}</h1>
            <p className="text-gray-300">{course?.courseDescription}</p>
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-1">
                <span className="text-yellow-400 text-xl">{avgReviewCount.toFixed(1)}</span>
                <div className="flex gap-1">
                  {[...Array(5)].map((_, index) => (
                    <Star
                      key={index}
                      className={`w-5 h-5 ${
                        index < Math.round(avgReviewCount)
                          ? 'text-yellow-400 fill-yellow-400'
                          : 'text-gray-400'
                      }`}
                    />
                  ))}
                </div>
              </div>
              <span className="text-gray-300">{`(${course?.ratingAndReview?.length} reviews)`}</span>
              <span className="text-gray-300">{`${course?.studentsEnrolled?.length} students enrolled`}</span>
            </div>
          </div>
          <div className="absolute w-[350px] p-6 bg-white rounded-xl shadow-xl right-0 top-24">
            <div className="text-gray-900">
              <div className="text-4xl font-bold mb-4">${course?.price}</div>
              <button
                onClick={() => setConfirmationModal(true)}
                className="w-full bg-blue-600 text-white py-4 px-6 rounded-lg hover:bg-blue-700 transition font-semibold text-lg"
              >
                Enroll Now
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-gray-100 w-11/12 max-w-7xl mx-auto flex flex-col items-start my-12">
        {/* Section 2 */}
        <div className="w-2/3">
          <div className="bg-white rounded-xl p-8 shadow-md mb-8">
            <h2 className="text-2xl font-bold mb-4">What you'll learn</h2>
            <p className="text-gray-700">{course?.whatYouWillLearn}</p>
          </div>

          <div className="space-y-6">
            <div className="flex justify-between items-center">
              <h2 className="text-2xl font-bold">Course Content</h2>
              <div className="text-blue-600 cursor-pointer hover:text-blue-700" 
                onClick={() => setOpenSectionsArray([])}>
                Collapse all sections
              </div>
            </div>

            <div className="space-y-4">
              {course?.courseContent?.map((section, index) => (
                <div key={index} className="bg-white rounded-xl shadow-md overflow-hidden">
                  <button
                    className="w-full px-8 py-6 flex items-center justify-between text-left hover:bg-gray-50"
                    onClick={() => {
                      setOpenSectionsArray(prev => 
                        prev.includes(index) 
                          ? prev.filter(i => i !== index)
                          : [...prev, index]
                      );
                    }}
                  >
                    <div className="flex items-center gap-3">
                      <ChevronDown className={`w-6 h-6 transition-transform ${
                        isOpen(index) ? 'transform rotate-180' : ''
                      }`} />
                      <span className="text-xl font-medium">{section.sectionName}</span>
                    </div>
                    <div className="text-gray-600">{`${section?.subSection.length} lectures`}</div>
                  </button>

                  {isOpen(index) && (
                    <div className="border-t border-gray-100">
                      {section?.subSection?.map((subSection, subIndex) => (
                        <div key={subIndex} 
                          className="px-8 py-4 flex items-start gap-3 hover:bg-gray-50"
                        >
                          <PlayCircle className="w-6 h-6 text-gray-400 mt-1" />
                          <div>
                            <p className="font-medium">{subSection?.title}</p>
                            <p className="text-gray-600 mt-1">{subSection?.description}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>

            {/* Author Section */}
            <div className="bg-white rounded-xl p-8 shadow-md mt-8">
              <h2 className="text-2xl font-bold mb-6">Instructor</h2>
              <div className="flex items-center gap-4">
                <img
                  className="w-16 h-16 rounded-full object-cover"
                  src={course?.instructor?.image}
                  alt="Instructor"
                />
                <div>
                  <h3 className="text-xl font-semibold">
                    {`${course?.instructor?.firstName} ${course?.instructor?.lastName}`}
                  </h3>
                  <p className="text-gray-600 mt-2">
                    Expert instructor with years of experience in web development and teaching.
                    Committed to helping students master modern development techniques.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {confirmationModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl p-8 max-w-md w-full">
            <h3 className="text-xl font-bold mb-2">You are not logged in</h3>
            <p className="text-gray-600 mb-6">Please log in to enroll in this course</p>
            <div className="flex gap-4">
              <button
                className="flex-1 bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700 transition"
                onClick={() => {
                  // Handle login navigation
                  setConfirmationModal(false);
                }}
              >
                Login
              </button>
              <button
                className="flex-1 border border-gray-300 py-2 px-4 rounded-lg hover:bg-gray-50 transition"
                onClick={() => setConfirmationModal(false)}
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

export default App;
